class Complex {
    int r, i;
public:
    Complex(int a=0, int b=0): r(a), i(b) {}
    Complex(const char* s) { r = s[0]-'0'; i = s[2]-'0'; }
    Complex(const Complex& c): r(c.r), i(c.i) {}
    Complex operator+(const Complex& b) const { return Complex(r+b.r, i+b.i); }
    Complex operator-(const Complex& b) const { return Complex(r-b.r, i-b.i); }
    Complex operator*(const Complex& b) const {
        return Complex(r*b.r - i*b.i, r*b.i + i*b.r);
    }
    Complex& operator+=(const Complex& b) { r += b.r; i += b.i; return *this; }
    Complex& operator-=(int n) { r -= n; return *this; }
    Complex& operator*=(const Complex& b) {
        int nr = r*b.r - i*b.i, ni = r*b.i + i*b.r;
        r = nr; i = ni; return *this;
    }
    friend ostream& operator<<(ostream& os, const Complex& c) {
        if (c.r && c.i) os << c.r << "+" << c.i << "i";
        else if (c.r) os << c.r;
        else if (c.i) os << c.i << "i";
        else os << 0;
        return os;
    }
};

